// Extract employee fields from webhook body
const body = $('Birthday Greeting Email Received').item.json.body;
const employeeName = body.name || '';
const employeeEmail = body.email || '';
const dateOfBirth = body.dateOfBirth || '';

if (!employeeName || !employeeEmail) {
  throw new Error('Missing required fields: name and/or email');
}

return [{ json: { employeeName, employeeEmail, dateOfBirth } }];

// LOG_BIRTHDAY_EMAIL: Replace this node with actual email sending when email provider is configured
const employeeName = $('Extract Employee Fields').item.json.employeeName;
const employeeEmail = $('Extract Employee Fields').item.json.employeeEmail;
const dateOfBirth = $('Extract Employee Fields').item.json.dateOfBirth;
const emailBody = $json.response || '(email body not available)';
const subject = `Happy Birthday, ${employeeName}! 🎂`;

console.log(`[BIRTHDAY EMAIL LOG]`);
console.log(`To: ${employeeName} <${employeeEmail}>`);
console.log(`Subject: ${subject}`);
console.log(`Date of Birth: ${dateOfBirth}`);
console.log(`Body: ${emailBody}`);

return [{ json: {
  status: 'logged',
  employee: employeeName,
  email: employeeEmail,
  subject,
  dateOfBirth,
  emailBody
} }];
